mapper.select:


WHERE 1 = 1

    AND jc.job_type_id = #{jobType.id}



    AND jc.name LIKE #{_name}


    AND jc.monday = #{monday}


    AND jc.tuesday = #{tuesday}


    AND jc.wednesday = #{wednesday}


    AND jc.thursday = #{thursday}


    AND jc.friday = #{friday}


    AND jc.saturday = #{saturday}


    AND jc.sunday = #{sunday}
